import java.util.Scanner;

public class LongestWordFinder {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.println("Enter a sentence terminated by . or ?:");
        String s = sc.nextLine().trim();

        // Strip terminating punctuation and append space
        char last = s.charAt(s.length() - 1);
        if (last == '.' || last == '?') {
            s = s.substring(0, s.length() - 1);
        }
        s = s + " ";

        String word = "";
        String longestWord = "";

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch != ' ') {
                word = word + ch;
            } else {
                if (word.length() > longestWord.length()) {
                    longestWord = word;
                }
                word = "";
            }
        }

        System.out.println("Longest word: " + longestWord);
        System.out.println("Length: " + longestWord.length());
    }
}
/*
VARIABLE DESCRIPTION TABLE:
Variable Name | Data Type | Purpose
s             | String    | Input sentence
word          | String    | Holds currently extracted word
longestWord   | String    | Stores longest word found so far
i             | int       | Loop index for sentence traversal
ch            | char      | Current character extracted at index i
*/
```

